CREATE COLUMN TABLE "TEST_AP"."OBSJ" ("ID" INTEGER CS_INT NOT NULL , "Type" NVARCHAR(100), "Desc" NVARCHAR(100), "Status" NVARCHAR(1) DEFAULT 'S', "Schedule" NVARCHAR(1) DEFAULT 'O', "NextDate" LONGDATE CS_LONGDATE, "NextTime" SMALLINT CS_INT, "BFParams" NCLOB MEMORY THRESHOLD 1000, "EFParams" NCLOB MEMORY THRESHOLD 1000, "BFRetry" INTEGER CS_INT DEFAULT 0, "EFRetry" INTEGER CS_INT DEFAULT 0, "RunAs" SMALLINT CS_INT, "Message" NVARCHAR(200), "RunType" NVARCHAR(1) DEFAULT 'M', PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE 